@Override
    public void renderEffect(long appliedAtWorldTime, int amplifier, LivingEntity livingEntity, float delta, MatrixStack matrixStack, VertexConsumerProvider vertexConsumers, int light) {
        if (livingEntity.getHealth() <= 0 || !livingEntity.isAlive()) { return; }
        var itemRenderer = MinecraftClient.getInstance().getItemRenderer();
        var camera =  MinecraftClient.getInstance().gameRenderer.getCamera();
        var direction = camera.getPos().subtract(livingEntity.getPos()).normalize().multiply(livingEntity.getWidth() * 0.5F);

        matrixStack.push();
        var verticalOffset = (livingEntity.getHeight() / livingEntity.getScale()) * 0.75F;
        matrixStack.translate(direction.x, verticalOffset, direction.z);

        matrixStack.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(180F + (float)Math.toDegrees(Math.atan2(direction.x, direction.z)) ));
        matrixStack.multiply(RotationAxis.POSITIVE_X.rotationDegrees(camera.getPitch()));

        CustomModels.render(GLOWING_RENDER_LAYER, itemRenderer, modelId,
                matrixStack, vertexConsumers, light, livingEntity.getId());

        matrixStack.pop();
    }

public void render(PoseStack pMatrixStack, MultiBufferSource pBuffer, int pPackedLight, Player pLivingEntity, float pLimbSwing, float pLimbSwingAmount, float pPartialTicks, float pAgeInTicks, float pNetHeadYaw, float pHeadPitch) {
            float percent = getRenderPercent(pLivingEntity);
            if (percent > 0) {
                float f = (float) pLivingEntity.tickCount + pPartialTicks;
                float offset = Mth.sin(f * 2) * 0.75f * percent;
                pMatrixStack.translate(offset, 0, 0);
                pMatrixStack.scale(1.01f, 1.01f, 1.01f);
                int color = RenderHelper.colorf(.988f * percent, .313f * percent, .968f * percent, percent);
                this.getParentModel().renderToBuffer(pMatrixStack, pBuffer.getBuffer(RenderHelper.CustomerRenderType.magic(this.getTextureLocation(pLivingEntity))), LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, color);
            }
        }

@Override
        public void render(PoseStack poseStack, AbstractSpellCastingMob animatable, BakedGeoModel bakedModel, RenderType renderType2, MultiBufferSource bufferSource, VertexConsumer buffer, float partialTick, int packedLight, int packedOverlay) {
            if (EnergySwirlLayer.shouldRender(animatable, shouldRenderFlag)) {
                float f = (float) animatable.tickCount + partialTick;
                var renderType = EnergySwirlLayer.getRenderType(TEXTURE, f);
                VertexConsumer vertexconsumer = bufferSource.getBuffer(renderType);
                poseStack.pushPose();
                bakedModel.getBone("body").ifPresent((rootBone) -> {
                    rootBone.getChildBones().forEach(bone -> {
                        bone.updateScale(1.1f, 1.1f, 1.1f);
                    });
                });
                this.getRenderer().actuallyRender(poseStack, animatable, bakedModel, renderType, bufferSource, vertexconsumer, true, partialTick,
                        packedLight, OverlayTexture.NO_OVERLAY, COLOR);

                bakedModel.getBone("body").ifPresent((rootBone) -> {
                    rootBone.getChildBones().forEach(bone -> {
                        bone.updateScale(1f, 1f, 1f);
                    });
                });
                poseStack.popPose();
            }
        }

@Override
    public void render(PoseStack poseStack, AbstractSpellCastingMob animatable, BakedGeoModel bakedModel, RenderType renderType, MultiBufferSource bufferSource, VertexConsumer buffer, float partialTick, int packedLight, int packedOverlay) {
        if (animatable.isAutoSpinAttack()) {
            poseStack.pushPose();
            for (int i = 0; i < 3; ++i) {
                poseStack.pushPose();
                float f = (animatable.tickCount + partialTick) + (float) (-(45 + i * 5));
                poseStack.mulPose(Axis.YP.rotationDegrees(f));
                float f1 = 0.75F * (float) i;
                poseStack.scale(f1, f1, f1);
                poseStack.translate(0, -1 + (double) (-0.2F + 0.6F * (float) i), 0);
                var rendertype = RenderType.entityCutoutNoCull(modelProvider.getTextureResource(animatable));
                getRenderer().actuallyRender(poseStack, animatable, modelProvider.getBakedModel(modelProvider.getModelResource(animatable)), rendertype, bufferSource, bufferSource.getBuffer(rendertype), true, partialTick, LightTexture.FULL_BRIGHT, packedOverlay, -1);
                poseStack.popPose();
            }
            poseStack.popPose();
        }
    }
